// Same Gamma values and one-cycle latency. Three true dual-port ROMs
// serve six channels without six independent single-port memory blocks.
// INIT constants generated from gamma_inv2p2_8b.mem; tools/check_gamma_dual.py
// verifies the generated bytes against that source before tests/builds.
module artflow_pair_normalize #(parameter LUT_FILE="rtl/gamma_conrrection/gamma_inv2p2_8b.mem")(
 input logic clk,rst_n,de,hs,vs,input logic [10:0] x,y,
 input logic [31:0] original_pixel,style_pixel,
 output logic ode,ohs,ovs,output logic [10:0] ox,oy,
 output wire [23:0] original_rgb,style_rgb);
wire [23:0] gi,gs;
logic [24:0] pi,ps;
for(genvar c=0;c<3;c=c+1)begin:channels
 EFX_DPRAM10 #(.READ_WIDTH_A(8),.WRITE_WIDTH_A(8),.READ_WIDTH_B(8),.WRITE_WIDTH_B(8),
 .OUTPUT_REG_A(1'b0),.OUTPUT_REG_B(1'b0),
 .INIT_0(256'h62605f5d5c5a5957555452504e4c4a48464442403d3b3835322e2b27221c1500),
 .INIT_1(256'h87868584838281807f7e7d7c7b7a78777675747372706f6e6d6b6a6967666563),
 .INIT_2(256'ha3a2a1a0a09f9e9d9c9c9b9a9998979796959493929190908f8e8d8c8b8a8988),
 .INIT_3(256'hbab9b8b8b7b6b6b5b4b4b3b2b2b1b0afafaeadadacabaaaaa9a8a7a7a6a5a4a4),
 .INIT_4(256'hcecdcdcccbcbcacac9c8c8c7c7c6c5c5c4c3c3c2c2c1c0c0bfbebebdbcbcbbba),
 .INIT_5(256'he0dfdfdedddddcdcdbdbdadad9d9d8d7d7d6d6d5d5d4d4d3d2d2d1d1d0cfcfce),
 .INIT_6(256'hf0efefeeeeededececebebeaeae9e9e8e8e7e7e6e6e5e5e4e4e3e3e2e2e1e1e0),
 .INIT_7(256'hfffffefefdfdfcfcfbfbfafaf9f9f9f8f8f7f7f6f6f5f5f4f4f3f3f2f2f1f1f0)
 ) rom(.CLKA(clk),.CLKEA(de),.WEA(1'b0),.RSTA(!rst_n),.ADDRENA(1'b1),.WDATAA(8'd0),.ADDRA({2'b0,original_pixel[c*8+:8]}),.RDATAA(gi[c*8+:8]),
       .CLKB(clk),.CLKEB(de),.WEB(1'b0),.RSTB(!rst_n),.ADDRENB(1'b1),.WDATAB(8'd0),.ADDRB({2'b0,style_pixel[c*8+:8]}),.RDATAB(gs[c*8+:8]));
end
assign original_rgb=ode?(pi[24]?pi[23:0]:gi):24'd0;
assign style_rgb=ode?(ps[24]?ps[23:0]:gs):24'd0;
always_ff @(posedge clk or negedge rst_n)
 if(!rst_n)begin ode<=0;ohs<=0;ovs<=0;ox<=0;oy<=0;pi<=0;ps<=0;end
 else begin ode<=de;ohs<=hs;ovs<=vs;ox<=x;oy<=y;pi<=original_pixel[24:0];ps<=style_pixel[24:0];end
endmodule
